/**
 * Landing compiled TSX in a design.
 *
 * `compileTsx` produces a complete, self-consistent circuit-json document — with its own
 * ids, which were generated by tscircuit and know nothing about the ids already in the
 * design. Merging two such documents naively collides: both call their first component
 * `source_component_0`.
 *
 * `mergeCompiled` re-ids the incoming document into a namespace of its own, records where
 * every element came from, and then hands the result to `merge_circuit_json` — the same
 * validated door any other client uses. It adds no new way to mutate a design.
 */

import type { AnyCircuitElement } from "circuit-json"
import type { Result, ValidationError } from "@syntrix/shared"
import { newElementId } from "@syntrix/shared"
import { apply } from "./apply"
import { buildIndex } from "./index-view"
import type { Design, MetaEntry, Provenance } from "./types"

/** Every circuit-json field that holds an element id, by suffix. */
const ID_SUFFIX = /_id$/
const ID_LIST_SUFFIX = /_ids$/

export interface MergeCompiledOptions {
  strategy?: "replace_all" | "merge_by_name" | "append_only"
  /** Recorded on every element the merge brings in. */
  provenance?: Omit<Provenance, "at" | "source"> & { source?: Provenance["source"] }
}

/**
 * Rewrite every id in a document so it cannot collide with ids already in use.
 *
 * Works structurally rather than from a list of known fields: circuit-json has hundreds
 * of element types and any of them may gain another reference field, so keying off the
 * `_id` / `_ids` naming convention is what keeps this correct as the spec moves. Only
 * ids the document defines are rewritten — a value that refers to nothing inside the
 * document (a layer name, a net name) is left exactly as it is.
 */
export const reidElements = (elements: AnyCircuitElement[]): AnyCircuitElement[] => {
  const mapping = new Map<string, string>()

  // Pass 1: every id this document defines. An element's own id is the field named after
  // its type (`source_component` → `source_component_id`), which is also the only one
  // guaranteed to be a definition rather than a reference.
  for (const element of elements) {
    const record = element as unknown as Record<string, unknown>
    const ownIdField = `${element.type}_id`
    const ownId = record[ownIdField]
    if (typeof ownId === "string" && !mapping.has(ownId)) {
      mapping.set(ownId, newElementId(element.type))
    }
  }

  // Pass 2: rewrite definitions and references alike, at any depth.
  const rewrite = (value: unknown, key?: string): unknown => {
    if (Array.isArray(value)) {
      return value.map((item) =>
        typeof item === "string" && key && ID_LIST_SUFFIX.test(key)
          ? (mapping.get(item) ?? item)
          : rewrite(item),
      )
    }
    if (value && typeof value === "object") {
      return Object.fromEntries(
        Object.entries(value as Record<string, unknown>).map(([k, v]) => [k, rewrite(v, k)]),
      )
    }
    if (typeof value === "string" && key && ID_SUFFIX.test(key)) {
      return mapping.get(value) ?? value
    }
    return value
  }

  return elements.map((element) => rewrite(element) as AnyCircuitElement)
}

/**
 * Merge a compiled document into a design.
 *
 * Provenance is recorded for every element that survives the merge, so the operation log
 * is not the only way to answer "where did this come from" — a design loaded fresh still
 * knows which parts of it an agent wrote.
 */
export const mergeCompiled = (
  design: Design,
  elements: AnyCircuitElement[],
  options: MergeCompiledOptions = {},
): Result<Design, ValidationError[]> => {
  const reided = reidElements(elements)

  const merged = apply(design, {
    type: "merge_circuit_json",
    elements: reided,
    strategy: options.strategy ?? "merge_by_name",
  })
  if (!merged.ok) return merged

  const provenance: Provenance = {
    source: options.provenance?.source ?? "tsx",
    at: new Date().toISOString(),
    ...(options.provenance?.operationId ? { operationId: options.provenance.operationId } : {}),
    ...(options.provenance?.runId ? { runId: options.provenance.runId } : {}),
  }

  // Only elements that actually landed get provenance: `merge_by_name` may have dropped
  // an incoming element, and claiming authorship of something that is not in the document
  // would make the sidecar lie.
  const present = new Set(
    merged.value.circuit.map((element) => {
      const record = element as unknown as Record<string, unknown>
      return record[`${element.type}_id`]
    }),
  )

  const meta: Record<string, MetaEntry> = { ...merged.value.meta }
  for (const element of reided) {
    const record = element as unknown as Record<string, unknown>
    const id = record[`${element.type}_id`]
    if (typeof id !== "string" || !present.has(id)) continue
    meta[id] = { ...meta[id], provenance }
  }

  return { ok: true, value: { ...merged.value, meta } }
}

/**
 * Which components a compiled document would replace in this design.
 *
 * The caller shows this before merging, because `merge_by_name` overwrites silently and
 * a user who asked for "add a decoupling cap" should not discover that R1 was rebuilt.
 */
export const mergeImpact = (
  design: Design,
  elements: AnyCircuitElement[],
): { replaced: string[]; added: string[] } => {
  const existing = buildIndex(design.circuit).componentsByName
  const incoming = buildIndex(elements).componentsByName

  const replaced: string[] = []
  const added: string[] = []
  for (const name of incoming.keys()) {
    if (existing.has(name)) replaced.push(name)
    else added.push(name)
  }
  return { replaced, added }
}
